import axios from 'axios'
import { React, useEffect, useState } from 'react'

const Members = () => {
    const [members, setMembers] = useState([])

    useEffect(() => {
        const fetchAllMembers = async () => {
            try {
                const res = await axios.get("http://localhost:8800")
                setMembers(res.data)
            } catch(err) {
                console.log(err)
            }
        }
        fetchAllMembers()
    }, [])

    function membershipStatus(membership) {
        if (membership) {
            return "Yes"
        }
        return "No"
    }

    return ( 
        <div>
            <h1>Members List</h1>
            <div className="members">
                {members.map((member) => (
                    <div className="member" key={member.id}>
                        {member.cover && <img src="" alt="" />}
                        <h2>Member name: {member.name}</h2>
                        <h4>Membership: {membershipStatus(member.membership)}</h4>
                        <h4>Age: {member.age}</h4>
                    </div>
                ))}
            </div>
        </div>
    )
}

export default Members
